<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Compra extends Model {protected $guarded=[]; protected $casts=['registrado_at'=>'datetime','contabilizado_at'=>'datetime']; public function proveedor(){return $this->belongsTo(Tercero::class,'proveedor_id');} public function usuario(){return $this->belongsTo(User::class,'user_id');} public function detalles(){return $this->hasMany(CompraDetalle::class);} public function pagos(){return $this->hasMany(CompraPago::class);} public function pagosProveedor(){return $this->hasMany(PagoProveedorAplicacion::class);} public function documento(){return $this->belongsTo(Documento::class);}}
